// Verus program: element-wise bitwise AND of two equal-length u8 vectors.

use vstd::prelude::*;

verus! {

fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires
        a.len() == b.len(),
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == (a[i] & b[i]),
{
    let n = a.len();
    let mut result: Vec<u8> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == a.len(),
            n == b.len(),
            result.len() == i,
            i <= n,
            forall|j: int| 0 <= j < i ==> result[j] == (a[j] & b[j]),
        decreases
            n - i,
    {
        result.push(a[i] & b[i]);
        i += 1;
    }

    result
}

} // verus!